def is_too_close(p1, p2):
    for v1, v2 in zip(p1, p2):
        if abs(v1 - v2) >= 2:
            return False
    return True

def solve_m(m):
    perms = list(itertools.permutations(range(1, m + 1)))
    n_perms = len(perms)
    adj = [0] * n_perms
    for i in range(n_perms):
        for j in range(i + 1, n_perms):
            if is_too_close(perms[i], perms[j]):
                adj[i] |= (1 << j)
                adj[j] |= (1 << i)

    max_val = 0
    def backtrack_mis(candidates, current_size):
        nonlocal max_val
        if candidates == 0:
            if current_size > max_val:
                max_val = current_size
            return

        if current_size + bin(candidates).count('1') <= max_val:
            return

        # Pick node with smallest degree (heuristic for MIS)
        best_v = -1
        min_deg = 1000

        temp_candidates = candidates
        while temp_candidates:
            v = (temp_candidates & -temp_candidates).bit_length() - 1
            deg = bin(adj[v] & candidates).count('1')
            if deg < min_deg:
                min_deg = deg
                best_v = v
            temp_candidates &= ~(1 << v)

        # Option 1: Include best_v
        backtrack_mis(candidates & ~adj[best_v] & ~(1 << best_v), current_size + 1)
        # Option 2: Exclude best_v
        backtrack_mis(candidates & ~(1 << best_v), current_size)

    backtrack_mis((1 << n_perms) - 1, 0)
    return max_val

