import itertools
import networkx as nx

def is_close(p1, p2):
    for i in range(len(p1)):
        if abs(p1[i] - p2[i]) > 1:
            return False
    return True

def solve_k(k):
    perms = list(itertools.permutations(range(1, k+1)))
    G = nx.Graph()
    for i in range(len(perms)):
        G.add_node(i)
    for i in range(len(perms)):
        for j in range(i+1, len(perms)):
            if is_close(perms[i], perms[j]):
                G.add_edge(i, j)

    # To find the maximum independent set, we can use the fact that 
    # for k=4, there are only 24 vertices.
    # We can use a recursive backtracking algorithm.

    def find_max_independent_set(graph):
        nodes = list(graph.nodes())
        max_set = []

        def backtrack(current_set, candidates):
            nonlocal max_set
            if not candidates:
                if len(current_set) > len(max_set):
                    max_set = current_set[:]
                return

            if len(current_set) + len(candidates) <= len(max_set):
                return

            v = candidates[0]
            # Case 1: v is in the independent set
            new_candidates = [c for c in candidates if c != v and not graph.has_edge(v, c)]
            backtrack(current_set + [v], new_candidates)

            # Case 2: v is not in the independent set
            new_candidates = [c for c in candidates if c != v]
            backtrack(current_set, new_candidates)

        backtrack([], nodes)
        return len(max_set)

    return find_max_independent_set(G)

