    adj = [[] for _ in range(len(perms))]
    for i in range(len(perms)):
        for j in range(i+1, len(perms)):
            if is_close(perms[i], perms[j]):
                adj[i].append(j)
                adj[j].append(i)

    n = len(perms)
    complement_adj = [[] for _ in range(n)]
    for i in range(n):
        neighbors = set(adj[i])
        for j in range(n):
            if i != j and j not in neighbors:
                complement_adj[i].append(j)

    max_clique_size = [0]

    def bron_kerbosch(r, p, x):
        if not p and not x:
            max_clique_size[0] = max(max_clique_size[0], len(r))
            return

        if not p:
            return

        if len(r) + len(p) <= max_clique_size[0]:
            return

        # Pivot
        u = max(p | x, key=lambda node: len(set(complement_adj[node]) & p))

        # We need to iterate over p \ neighbors(u)
        u_neighbors = set(complement_adj[u])
        for v in list(p - u_neighbors):
            bron_kerbosch(r | {v}, p & set(complement_adj[v]), x & set(complement_adj[v]))
            p.remove(v)
            x.add(v)

    bron_kerbosch(set(), set(range(n)), set())
    return max_clique_size[0]

