            for c in range(k):
                if abs(perms[i][c] - perms[j][c]) > 1:
                    is_edge = False
                    break
            if is_edge:
                adj[i] |= (1 << j)
                adj[j] |= (1 << i)

    visited = [False] * n
    total_mis = 0
    for i in range(n):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                component.append(u)
                for v in range(n):
                    if (adj[u] & (1 << v)) and not visited[v]:
                        visited[v] = True
                        stack.append(v)

            comp_size = len(component)
            comp_adj = [0] * comp_size
            for idx1, u in enumerate(component):
                for idx2, v in enumerate(component):
                    if (adj[u] & (1 << v)):
                        comp_adj[idx1] |= (1 << idx2)

            memo = {}
            def solve_bitmask(mask):
                if mask == 0:
                    return 0
                if mask in memo:
