                v = (mask & -mask).bit_length() - 1
                res = max(solve_bitmask(mask ^ (1 << v)),
                          1 + solve_bitmask(mask & ~comp_adj[v] & ~(1 << v)))
                memo[mask] = res
                return res

            total_mis += solve_bitmask((1 << comp_size) - 1)
    return total_mis

