    G = nx.Graph()
    for i in range(len(perms)):
        G.add_node(i)
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            is_close = True
            for c in range(k):
                if abs(perms[i][c] - perms[j][c]) > 1:
                    is_close = False
                    break
            if is_close:
                G.add_edge(i, j)

    # Use a recursive function to find the size of the maximum independent set.
    # Since it's a small graph, we can use a simple backtracking algorithm.
    def get_max_indep_set(graph):
        nodes = list(graph.nodes())

        # Use a standard recursive algorithm for maximum independent set.
        # To speed it up, we use the fact that alpha(G) = |V| - omega(G_complement).
        # But since we want alpha(G), let's use a recursive approach for alpha.

        # A simple recursive approach:
        # alpha(G) = max(1 + alpha(G - {v} - N(v)), alpha(G - {v}))
        memo = {}

        def solve(current_nodes):
            nodes_tuple = tuple(sorted(current_nodes))
            if nodes_tuple in memo:
                return memo[nodes_tuple]

            if not current_nodes:
                return 0

            # Choose a node with the smallest degree to branch.
            v = min(current_nodes, key=lambda x: len([n for n in graph[x] if n in current_nodes]))

            # Option 1: Include v. The neighbors of v cannot be in the independent set.
            res1 = 1 + solve([n for n in current_nodes if n != v and n not in graph[v]])

            # Option 2: Exclude v.
            res2 = solve([n for n in current_nodes if n != v])

            memo[nodes_tuple] = max(res1, res2)
            return memo[nodes_tuple]

        return solve(set(graph.nodes()))

    return get_max_indep_set(G)

